use helios::devices::nvram::{Nvram, NvramError, CLOCK_CONTROL};
use helios::machine::{Machine, MachineProfile};

#[test]
fn unix_utc_uses_sun_year_origin_and_hardware_weekdays() {
    // Independent Gregorian calendar fixtures, not generated by the device.
    for (unix, fields) in [
        (0, [0, 0, 0, 5, 1, 1, 0x02]),
        (951_868_799, [0x59, 0x59, 0x23, 3, 0x29, 0x02, 0x32]),
        (1_794_832_496, [0x56, 0x34, 0x12, 2, 0x16, 0x11, 0x58]),
        (3_092_601_599, [0x59, 0x59, 0x23, 7, 0x31, 0x12, 0x99]),
    ] {
        let mut n = Nvram::default();
        n.initialize_sun_clock(unix).unwrap();
        assert_eq!(&n.image()[CLOCK_CONTROL + 1..], &fields);
        assert_eq!(Nvram::from_image(&n.image()).unwrap(), n);
    }
}

#[test]
fn startup_replaces_only_clock_fields_and_releases_latches_and_stop() {
    for profile in [
        MachineProfile::Ss5,
        MachineProfile::Ss20,
        MachineProfile::Axil320,
    ] {
        let mut n = profile.default_nvram();
        n.write(0x100, 0xaa).unwrap();
        let original = n.image();
        n.write(CLOCK_CONTROL, 0x80).unwrap();
        n.write(CLOCK_CONTROL + 1, 0x80).unwrap();
        n.write(CLOCK_CONTROL, 0).unwrap(); // stop oscillator
        n.write(CLOCK_CONTROL, 0xc0).unwrap();
        n.write(CLOCK_CONTROL + 6, 0xff).unwrap(); // incomplete staged edit
        n.initialize_sun_clock(951_868_799).unwrap();
        assert_eq!(&n.image()[..CLOCK_CONTROL], &original[..CLOCK_CONTROL]);
        assert_eq!(n.read(CLOCK_CONTROL).unwrap(), 0);
        n.advance_seconds(1);
        assert_eq!(&n.image()[CLOCK_CONTROL + 1..], &[0, 0, 0, 4, 1, 3, 0x32]);
    }
}

#[test]
fn out_of_range_initialization_is_atomic_and_defaults_stay_deterministic() {
    let mut n = Nvram::default();
    n.write(CLOCK_CONTROL, 0x40).unwrap();
    n.advance_seconds(123);
    let before = n.clone();
    for unix in [3_092_601_600, u64::MAX] {
        assert_eq!(
            n.initialize_sun_clock(unix),
            Err(NvramError::ClockOutOfRange)
        );
        assert_eq!(n, before);
    }
    assert_eq!(
        &Nvram::default().image()[CLOCK_CONTROL..],
        &[0, 0, 0, 0, 7, 1, 1, 0x32]
    );
}

#[test]
fn machine_resets_retain_seeded_time_and_guest_time_still_advances() {
    for profile in [
        MachineProfile::Ss5,
        MachineProfile::Ss20,
        MachineProfile::Axil320,
    ] {
        let mut n = profile.default_nvram();
        n.initialize_sun_clock(1_794_832_496).unwrap();
        let mut m = Machine::with_profile(profile, 16 * 1024 * 1024, &[1, 0, 0, 0], n).unwrap();
        m.advance_seconds(4);
        let saved = m.bus.devices().unwrap().nvram.image();
        assert_eq!(
            &saved[CLOCK_CONTROL + 1..],
            &[0, 0x35, 0x12, 2, 0x16, 0x11, 0x58]
        );
        m.reset();
        assert_eq!(m.bus.devices().unwrap().nvram.image(), saved);
        m.bus.devices_mut().unwrap().reset.write(1);
        assert!(matches!(
            m.step().unwrap(),
            helios::cpu::Step::SoftwareReset { .. }
        ));
        assert_eq!(m.bus.devices().unwrap().nvram.image(), saved);
    }
}
